def _cell(text):
    """Strip surrounding whitespace and escape pipes so the cell stays one column."""
    return text.strip().replace("|", "\\|")


def _line(cells):
    return "| " + " | ".join(_cell(c) for c in cells) + " |"


def to_markdown(rows):
    """Render rows (first row is the header) as a GitHub markdown table."""
    if not rows:
        raise ValueError("no rows")
    header = rows[0]
    if not header:
        raise ValueError("empty header")
    for i, row in enumerate(rows):
        if len(row) != len(header):
            raise ValueError(f"row {i} has {len(row)} cells, header has {len(header)}")
    separator = "| " + " | ".join("---" for _ in header) + " |"
    lines = [_line(header), separator] + [_line(row) for row in rows[1:]]
    return "\n".join(lines)

